 403:     private void addChange(
 404:         Map<String, FieldChange> changes,
 405:         String field,
 406:         Object oldValue,
 407:         Object newValue
 408:     ) {
 409:         if (!valuesEqual(oldValue, newValue)) {
 410:             changes.put(field, new FieldChange(asHistoryValue(oldValue), asHistoryValue(newValue)));
 411:         }
 412:     }
 413: 
 414:     private boolean valuesEqual(Object oldValue, Object newValue) {
 415:         if (oldValue instanceof BigDecimal oldDecimal && newValue instanceof BigDecimal newDecimal) {
 416:             return oldDecimal.compareTo(newDecimal) == 0;
 417:         }
 418:         return Objects.equals(oldValue, newValue);
 419:     }
 420: 
 421:     private String asHistoryValue(Object value) {
 422:         return value instanceof BigDecimal decimal ? decimal.toPlainString() : Objects.toString(value, null);
 423:     }
 424: 
 425:     private boolean isDuplicateKey(DataIntegrityViolationException exception) {
 426:         Throwable current = exception;
 427:         while (current != null) {
 428:             if (current instanceof DuplicateKeyException) {
 429:                 return true;
 430:             }
 431:             if (current instanceof SQLException sqlException
 432:                 && ("23505".equals(sqlException.getSQLState()) || sqlException.getErrorCode() == 1062)) {
 433:                 return true;
 434:             }
 435:             current = current.getCause();
 436:         }
 437:         return false;
 438:     }
 439: }
