  17: public final class FrameSpecifications {
  18: 
  19:     private FrameSpecifications() {
  20:     }
  21: 
  22:     public static Specification<Frame> matching(FrameSearchCriteria criteria) {
  23:         return (root, query, builder) -> {
  24:             List<Predicate> predicates = new ArrayList<>();
  25: 
  26:             if (criteria.query() != null) {
  27:                 String pattern = "%" + escapeLike(criteria.query().toLowerCase(Locale.ROOT)) + "%";
  28:                 predicates.add(builder.or(
  29:                     like(builder, root.get("frameId"), pattern),
  30:                     like(builder, root.get("location").get("address"), pattern),
  31:                     like(builder, root.get("location").get("town"), pattern),
  32:                     like(builder, root.get("site").get("station"), pattern),
  33:                     like(builder, root.get("site").get("airport"), pattern),
  34:                     like(builder, root.get("site").get("siteNumber"), pattern)
  35:                 ));
  36:             }
  37: 
  38:             addExact(predicates, builder, root.get("status"), criteria.status());
  39:             addExact(predicates, builder, root.get("mediaType"), criteria.mediaType());
  40:             addExact(predicates, builder, root.get("environment"), criteria.environment());
  41:             addExact(predicates, builder, root.get("format"), criteria.format());
  42:             addExact(predicates, builder, root.get("location").get("region"), criteria.region());
  43: 
  44:             return builder.and(predicates.toArray(Predicate[]::new));
  45:         };
  46:     }
  47: 
  48:     private static Predicate like(CriteriaBuilder builder, Path<?> path, String pattern) {
  49:         return builder.like(lower(builder, path), pattern, '\\');
  50:     }
  51: 
  52:     private static void addExact(
  53:         List<Predicate> predicates,
  54:         CriteriaBuilder builder,
  55:         Path<?> path,
  56:         String value
  57:     ) {
  58:         if (value != null) {
  59:             predicates.add(builder.equal(lower(builder, path), value.toLowerCase(Locale.ROOT)));
  60:         }
  61:     }
  62: 
  63:     private static Expression<String> lower(CriteriaBuilder builder, Path<?> path) {
  64:         return builder.lower(path.as(String.class));
  65:     }
  66: 
  67:     private static String escapeLike(String value) {
  68:         return value.replace("\\", "\\\\").replace("%", "\\%").replace("_", "\\_");
  69:     }
