  73:     @Transactional
  74:     public FrameResponse createFrame(CreateFrameRequest request) {
  75:         return createFrame(request, HistoryEventType.CREATED, HistorySource.MANUAL);
  76:     }
  77: 
  78:     @Transactional(propagation = Propagation.REQUIRES_NEW)
  79:     public FrameResponse createImportedFrame(CreateFrameRequest request) {
  80:         return createFrame(request, HistoryEventType.IMPORTED, HistorySource.CSV_UPLOAD);
