 121:     @Transactional(readOnly = true)
 122:     public List<FrameHistoryResponse> getFrameHistory(String frameId) {
 123:         if (!repository.existsById(frameId)) {
 124:             throw new FrameNotFoundException(frameId);
 125:         }
 126:         return historyRepository.findByFrameFrameIdOrderByOccurredAtDescIdDesc(frameId).stream()
 127:             .map(history -> new FrameHistoryResponse(
 128:                 history.getEventType(),
 129:                 history.getOccurredAt(),
 130:                 history.getSource(),
 131:                 history.getChangedFields()
 132:             ))
 133:             .toList();
 134:     }
