 136:     @Transactional
 137:     public FrameResponse replaceFrame(String frameId, UpdateFrameRequest request) {
 138:         Frame existing = repository.findById(frameId)
 139:             .orElseThrow(() -> new FrameNotFoundException(frameId));
 140:         Instant occurredAt = now();
 141:         Frame replacement = mapper.toReplacement(existing, request, toLocalDateTime(occurredAt));
 142:         Map<String, FieldChange> changes = changedFields(existing, replacement);
 143:         if (changes.isEmpty()) {
 144:             return mapper.toResponse(existing);
 145:         }
 146: 
 147:         Frame saved = repository.saveAndFlush(replacement);
 148:         entityManager.refresh(saved);
 149:         historyRepository.save(new FrameHistory(
 150:             saved,
 151:             HistoryEventType.UPDATED,
 152:             occurredAt,
 153:             HistorySource.MANUAL,
 154:             changes
 155:         ));
 156:         return mapper.toResponse(saved);
 157:     }
