 179:         Map<String, FieldChange> changes = new LinkedHashMap<>();
 180:         addChange(changes, "mediaType", oldFrame.getMediaType(), newFrame.getMediaType());
 181:         addChange(changes, "format", oldFrame.getFormat(), newFrame.getFormat());
 182:         addChange(changes, "environment", oldFrame.getEnvironment(), newFrame.getEnvironment());
 183:         addChange(changes, "status", oldFrame.getStatus(), newFrame.getStatus());
 184:         addChange(changes, "statusReason", oldFrame.getStatusReason(), newFrame.getStatusReason());
 185:         addLocationChanges(changes, oldFrame.getLocation(), newFrame.getLocation());
 186:         addSiteChanges(changes, oldFrame.getSite(), newFrame.getSite());
 187:         addTechnicalChanges(changes, oldFrame.getTechnical(), newFrame.getTechnical());
 188:         addCommercialChanges(changes, oldFrame.getCommercial(), newFrame.getCommercial());
 189:         addIntegrationChanges(changes, oldFrame.getIntegrations(), newFrame.getIntegrations());
 190:         return changes;
 191:     }
